// Toma el output crudo del nodo anterior (AI Agent)
const rawOutput = $input.item.json.output;

let parsedOutput;

try {
  // Si el string viene con \n literales, JSON.parse ya los interpreta bien
  // porque \n dentro de comillas es válido en JSON
  parsedOutput = JSON.parse(rawOutput);
} catch (error) {
  // Fallback: a veces el modelo envuelve el JSON en ```json ... ```
  const cleaned = rawOutput
    .replace(/```json/g, '')
    .replace(/```/g, '')
    .trim();

  try {
    parsedOutput = JSON.parse(cleaned);
  } catch (e2) {
    throw new Error(`No se pudo parsear el output como JSON: ${e2.message}`);
  }
}

return {
  json: parsedOutput
};

// Toma el output crudo del AI Agent (texto markdown con \n escapados)
const rawOutput = $input.item.json.output;

// Reemplaza los \n literales (backslash + n) por saltos de línea reales
const cleanText = rawOutput.replace(/\\n/g, '\n');

// Conversión básica markdown -> HTML (sin librerías)
let html = cleanText
  .replace(/\*\*(.*?)\*\*/g, '<b>$1</b>')      // negritas
  .replace(/^## (.*$)/gm, '<h2>$1</h2>')       // encabezados H2
  .replace(/^# (.*$)/gm, '<h1>$1</h1>')        // encabezados H1
  .replace(/\n/g, '<br>');                     // saltos de línea

return {
  json: {
    output: cleanText,
    outputHtml: html
  }
};

